mapper.select:
SELECT o.id AS order_id, o.account_id, o.order_code, o.subtotal_amount, o.shipping_fee, o.total_amount, o.order_status, o.payment_status, o.payment_method, o.shipping_full_name, o.shipping_phone_number, o.shipping_address, o.created_at, o.updated_at FROM orders o
(LOWER(o.shipping_full_name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR o.shipping_phone_number LIKE CONCAT('%', #{keyword}, '%'))
AND o.order_status = #{orderStatus}
AND o.payment_status = #{paymentStatus}
ORDER BY o.created_at ASC
ORDER BY o.created_at DESC
